mapper.select:
SELECT COUNT(*)
FROM event_participants
WHERE session_id = #{sessionId}

mapper.update:
UPDATE event_sessions
SET status = #{toStatus}
WHERE session_id = #{sessionId}
  AND status = #{fromStatus}

UPDATE event_sessions
SET status = 'FINISHED',
    finished_at = #{finishedAt}
WHERE session_id = #{sessionId}
  AND status = #{fromStatus}
